function widestSpacing(spots: number[], m: number): number {
  const s = [...spots].sort((a, b) => a - b);
  const fits = (d: number): boolean => {
    let count = 1, last = s[0];
    for (const x of s) if (x - last >= d) { count++; last = x; }
    return count >= m;
  };
  const gaps: number[] = [];
  for (let i = 0; i < s.length; i++) for (let j = i + 1; j < s.length; j++) gaps.push(s[j] - s[i]);
  gaps.sort((a, b) => b - a);
  for (const d of gaps) if (fits(d)) return d;
  return 0;
}

