function widestSpacing(spots: number[], m: number): number {
  const s = [...spots].sort((a, b) => a - b);
  const fits = (d: number): boolean => {
    let count = 1, last = s[0];
    for (let i = 1; i < s.length && count < m; i++) {
      if (s[i] - last >= d) { count++; last = s[i]; }
    }
    return count >= m;
  };
  let lo = 1, hi = s[s.length - 1] - s[0], best = 1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (fits(mid)) { best = mid; lo = mid + 1; }
    else hi = mid - 1;
  }
  return best;
}

